let client=null,user=null,profile={};
const clean=value=>String(value||'').replace(/[<>&"]/g,'').trim();
const css=`.profile-dialog{max-height:min(46rem,94vh);overflow:auto}.profile-hero{display:flex;align-items:center;gap:14px}.profile-avatar{display:grid;place-items:center;width:4.4rem;height:4.4rem;border:4px solid #fff;border-radius:50%;box-shadow:0 0 0 2px #d4e2dc;color:#173e38;font-size:1.8rem;font-weight:800}.profile-grid{display:grid;grid-template-columns:1fr 1fr;gap:.7rem}.profile-dialog textarea{box-sizing:border-box;width:100%;resize:vertical;border:1px solid #b9ccc4;border-radius:.55rem;padding:.72rem;font:inherit;background:#fff}.avatar-choices{border:0;padding:0;margin:0}.avatar-choices legend{font-size:.85rem;font-weight:700}.avatar-choices>div{display:flex;gap:.5rem;margin-top:.4rem}.avatar-choices label{position:relative}.avatar-choices input{position:absolute;opacity:0}.avatar-choices i{display:block;width:1.75rem;height:1.75rem;border:3px solid transparent;border-radius:50%;cursor:pointer}.avatar-choices input:checked+i{border-color:#173e38;box-shadow:0 0 0 2px #fff}@media(max-width:540px){.profile-grid{grid-template-columns:1fr}}`;
const style=document.createElement('style');style.textContent=css;document.head.append(style);
const dialog=document.createElement('dialog');dialog.id='profileDialog';dialog.className='auth-dialog profile-dialog';dialog.innerHTML=`<form class="auth-shell" id="profileForm"><button class="auth-close" type="button" id="closeProfile" aria-label="Close profile">×</button><p class="eyebrow">MY PROFILE</p><div class="profile-hero"><div class="profile-avatar" id="profileAvatar"><span>R</span></div><div><h2>Make Rebound yours.</h2><p>Your profile is private to your account.</p></div></div><label>Display name<input id="profileName" maxlength="60" autocomplete="name" placeholder="How should Rebound call you?"></label><label>About me<textarea id="profileAbout" maxlength="280" rows="3" placeholder="A small note about your goals."></textarea></label><div class="profile-grid"><label>Date of birth<input id="profileDob" type="date" max="${new Date().toISOString().slice(0,10)}"></label><label>Location<input id="profileLocation" maxlength="100" autocomplete="address-level2" placeholder="City, country"></label></div><fieldset class="avatar-choices"><legend>Avatar colour</legend><div>${['#f6b35f','#e9857f','#728bc4','#73a989','#9c7dc1'].map((color,index)=>`<label><input type="radio" name="avatarColor" value="${color}" ${index===0?'checked':''}><i style="background:${color}"></i></label>`).join('')}</div></fieldset><p id="profileStatus" class="auth-status" role="status"></p><button class="primary" id="saveProfile">Save profile</button><button class="auth-guest" type="button" id="signOut">Sign out</button></form>`;document.body.append(dialog);
const $=id=>document.getElementById(id);const status=message=>{$('profileStatus').textContent=message;};
function avatar(){const name=$('profileName').value||profile.display_name||user?.email||'R';const color=document.querySelector('[name="avatarColor"]:checked')?.value||profile.avatar_color||'#f6b35f';$('profileAvatar').style.background=color;$('profileAvatar').querySelector('span').textContent=clean(name).slice(0,1).toUpperCase()||'R';}
function fill(){ $('profileName').value=profile.display_name||'';$('profileAbout').value=profile.about||'';$('profileDob').value=profile.birth_date||'';$('profileLocation').value=profile.location||'';const selected=document.querySelector(`[name="avatarColor"][value="${profile.avatar_color||'#f6b35f'}"]`);if(selected)selected.checked=true;avatar(); }
async function load(){const {data,error}=await client.from('profiles').select('display_name,about,birth_date,location,avatar_color').eq('id',user.id).maybeSingle();if(error&&error.code!=='PGRST116')throw error;profile=data||{};}
async function open(){try{await load();fill();status('');dialog.showModal();}catch(error){status(error.code==='PGRST205'?'Profile storage is being set up. Please try again shortly.':error.message);dialog.showModal();}}
async function save(){const name=clean($('profileName').value),about=clean($('profileAbout').value),location=clean($('profileLocation').value),birth=$('profileDob').value,color=document.querySelector('[name="avatarColor"]:checked')?.value||'#f6b35f';if(name&&name.length<2)return status('Use at least two characters for your display name.');const button=$('saveProfile');button.disabled=true;button.textContent='Saving…';try{const {error}=await client.from('profiles').upsert({id:user.id,display_name:name||null,about:about||null,birth_date:birth||null,location:location||null,avatar_color:color},{onConflict:'id'});if(error)throw error;profile={display_name:name,about,birth_date:birth,location,avatar_color:color};status('Profile saved privately.');const account=$('accountButton');if(account){account.querySelector('span').textContent=name||user.email.split('@')[0];account.title=`Signed in as ${name||user.email}`;}}catch(error){status(error.code==='PGRST205'?'Profile storage needs the Supabase migration before it can save.':error.message||'Could not save your profile.');}finally{button.disabled=false;button.textContent='Save profile';}}
dialog.querySelector('#closeProfile').onclick=()=>dialog.close();dialog.querySelector('#profileForm').onsubmit=event=>{event.preventDefault();save();};dialog.querySelector('#signOut').onclick=()=>client.auth.signOut();dialog.querySelectorAll('[name="avatarColor"],#profileName').forEach(input=>input.oninput=avatar);
window.addEventListener('rebound:auth',event=>{client=event.detail.client;user=event.detail.user;if(user){const account=$('accountButton');if(account)account.onclick=open;}else profile={};});
